#!/bin/bash
# Prints the three IP addresses that appear most often in access.log,
# most frequent first. Ties are broken by first appearance in the log.
set -euo pipefail
cd "$(dirname "$0")"

awk '{
    ip = $1
    if (!(ip in count)) {
        order[++n] = ip
    }
    count[ip]++
}
END {
    for (i = 1; i <= n; i++) {
        print count[order[i]], order[i]
    }
}' access.log | sort -k1,1nr -s | head -n 3 | awk '{print $2}'
